import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"3D Diffusion Policy: Generalizable Visuomotor Policy Learning via Simple 3D Representations","description":"","frontmatter":{"title":"3D Diffusion Policy: Generalizable Visuomotor Policy Learning via Simple 3D Representations","arxiv":"2403.03954","date":"2024-03-06","authors":"Yanjie Ze, Gu Zhang, Kangning Zhang, Chenyuan Hu, Muhan Wang, Huazhe Xu","categories":"cs.RO, cs.CV, cs.LG","topics":"模仿学习, 3D 表示, 扩散策略","outline":[2,2]},"headers":[],"relativePath":"papers/2403.03954.md","filePath":"papers/2403.03954.md","lastUpdated":null}'),l={name:"papers/2403.03954.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="_3d-diffusion-policy-generalizable-visuomotor-policy-learning-via-simple-3d-representations" tabindex="-1">3D Diffusion Policy: Generalizable Visuomotor Policy Learning via Simple 3D Representations <a class="header-anchor" href="#_3d-diffusion-policy-generalizable-visuomotor-policy-learning-via-simple-3d-representations" aria-label="Permalink to &quot;3D Diffusion Policy: Generalizable Visuomotor Policy Learning via Simple 3D Representations&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2403.03954" target="_blank" rel="noreferrer">2403.03954</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-03-06</td></tr><tr><td><strong>作者</strong></td><td>Yanjie Ze, Gu Zhang, Kangning Zhang, Chenyuan Hu, Muhan Wang, Huazhe Xu</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>把单视角深度图裁剪并降采样成 512–1024 个点，用三层 MLP 压成 64 维向量作为扩散策略的条件，10 条演示就能学会大部分任务。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页当前指向 <strong>v7</strong>（RSS 2024 正式版），但 v7 不提供 HTML，只有 v1 的 LaTeXML 全文可抓。两版摘要的头条数字不同：v1 说相对 Diffusion Policy 有 <strong>55.3%</strong> 的相对提升，v7 摘要写 <strong>24.2%</strong>（对比基线口径已改）。本文正文数据全部取自 v1 全文并按 v1 口径引用；引用 24.2% 时请以 v7 为准。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视觉模仿学习的代价写在演示条数上。论文开篇给的具体数字是：Diffusion Policy 在每个真实任务上需要 100 到 200 条人工采集的演示，而这些演示是长时程、易失败的，采集过程动辄跨越数天。在线学习可以绕开这一点，但要付出安全性、自动复位、人工干预和额外硬件的代价。于是问题被收窄成一个很实际的形式：在纯离线的前提下，怎样让模仿学习算法用尽可能少的演示学到鲁棒且可泛化的技能。</p><p>这个问题重要，是因为它决定了机器人学习能不能离开实验室。每个新任务几百条演示意味着技能库的扩张速度被人力锁死；而多指手、可形变物体这类真正需要机器人的场景，恰恰是演示最贵的场景。DP3 给出的答案是换掉观测模态而不是换掉算法框架：扩散策略保持不动，把条件从图像换成点云。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>2D 图像策略在这条线上占据主流：Diffusion Policy、IBC、BC-RNN 都以图像为输入。它们的能力是真实的——在同一批任务上 Diffusion Policy 仍是最强的 2D 基线——但论文指出的失效模式很具体：在 MetaWorld Reach 这样只需要把夹爪移动到指定 3D 点的任务上，给 5 条演示，Diffusion Policy 学到的是一个近似平面的可达区域，IBC 更差，BC-RNN 几乎学不会（1000 次评测中成功次数分别是 327 / 285 / 0，DP3 是 415）。也就是说 2D 策略把三维外推问题降级成了二维插值。</p><p>另一条线是已有的 3D 策略：PerAct、GNFactor、RVT、Act3D、3D Diffuser Actor。论文对它们的批评分两点，且都是可核验的。第一是设定不实用：这些方法通过关键帧位姿抽取把模仿学习转成&quot;预测再规划&quot;，对高维连续控制（比如 22 维的 Allegro 手）不适配。第二是推理慢：PerAct 2.23 FPS、3D Diffuser Actor 1.67 FPS，无法支撑需要稠密指令的任务。这就解释了&quot;3D 表示为什么没被广泛采用&quot;——不是没人想到，而是当时的 3D 策略把 3D 和一套重架构绑在了一起。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用当时已有的知识，路径大致是这样的：先观察到 2D 策略的失败集中在空间外推，而不是语义识别；再注意到控制任务里真正需要的状态量是位姿和几何，颜色反而是干扰项（这一点在图像增强的文献里已有征兆：强增强能提高外观泛化但拖慢学习）；然后问一个反向的问题——如果 3D 表示是有用的，为什么已有的 3D 策略要那么重？</p><p>答案是那些方法把 3D 用在了重建和体素化上。若只需要一个&quot;场景里有什么、在哪里&quot;的紧凑摘要，稀疏点云 + 一个小编码器就够了。此时再看扩散策略：它的条件接口本来就是一个向量，换成什么模态都行。于是最小改动方案浮现：保留 Diffusion Policy 的全部决策部分，只把视觉分支换成点云编码器。剩下的工程判断（裁掉桌面和地面、降采样、扔掉颜色通道）都是从&quot;控制不需要场景理解&quot;这条直觉推出来的。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>控制任务需要的视觉信息比看起来少得多：它需要知道物体在三维空间的哪里，不需要知道物体长什么样。点云天然把前者显式化、把后者丢掉，因此同样条数的演示能覆盖更大的状态空间。让先前方法失效的是 2D 观测把深度折叠进了外观，让这个方法奏效的是&quot;用一个 64 维向量描述被裁剪过的稀疏三维场景&quot;——低维、去纹理、且与相机视角弱耦合。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以真实任务 Pour（夹爪抓碗、倾倒肉松、放回桌面）为例：</p><ol><li><strong>感知输入</strong>：单台 RealSense L515，取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">84</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">84</span></span></span></span> 的深度图，用相机内外参转成点云。全程只有一个视角，这是为了真实部署的可行性。</li><li><strong>裁剪</strong>：按任务预设的包围盒裁掉桌面和地面点。</li><li><strong>降采样</strong>：最远点采样（FPS）到 512 或 1024 个点。选 FPS 而非均匀采样，是为了让点覆盖整个空间并降低采样随机性。</li><li><strong>编码</strong>：三层 MLP + max-pooling + 投影头，中间穿插 LayerNorm，输出 64 维特征 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span>。不使用颜色通道。</li><li><strong>决策</strong>：以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 与机器人本体位姿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span> 为条件，用卷积式扩散策略把高斯噪声去噪成动作序列。噪声调度器用 DDIM，训练 100 步、推理 10 步，并且用 sample prediction 而非 epsilon prediction。</li><li><strong>执行</strong>：输出 7 维动作序列直接下发。</li></ol><p>训练侧：所有方法统一 3000 epoch、batch 128；仿真里演示由 RL 智能体生成（Adroit 用 VRL3、MetaWorld 用 BAC、其余用 PPO），真实任务由人工遥操作采集，每任务 40 条。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>决策模块是一个条件去噪扩散模型。反向过程从高斯噪声 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span></span></span></span></span></span></span></span> 出发迭代 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 步：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8991em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0556em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.1474em;">N</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">I</span><span class="mclose">)</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0556em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由噪声调度器决定。直觉上这就是一个带噪声的梯度下降：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 给出&quot;当前样本偏离数据流形的方向&quot;，每步沿该方向回退一点，再注入逐渐减小的噪声以保持多模态性。条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span></span></span></span> 只是把这个流形限制在&quot;当前场景下合理的动作&quot;这一子集上。</p><p>训练目标是标准的噪声预测：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">MSE</span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.5678em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">ˉ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8312em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0528em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">ˉ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">)</span></span></span></span></span></span></span></p><p>实现上用的是 sample prediction（直接预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span></span></span></span></span></span></span></span>）而非上式的 epsilon prediction。消融显示这一项对高维动作的收敛速度影响不小：去掉 sample prediction 后 6 任务均值从 63.2 掉到 59.0，而在 Hammer 上从 100 掉到 68。作者的解释是高维动作生成更适合直接回归干净样本，这属于经验结论，论文未给出理论论证。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>3D 是否真的有用？</strong> 72 个仿真任务（7 个 domain，覆盖双手、可形变、铰接物体）上 DP3 平均 73.9±24.9，Diffusion Policy 47.6±32.9。DP3 有近 30 个任务超过 90%，Diffusion Policy 不到 15 个；DP3 没有任何任务低于 10%，Diffusion Policy 有 10 个以上。真实机器人 4 任务各 10 次试验：DP3 85.0±11.2，图像版 35.0，深度版 20.0。</p><p><strong>赢在 3D 还是赢在低分辨率对 2D 不公平？</strong> 作者做了这个对照：把 Diffusion Policy 的输入从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">8</span><span class="mord"><span class="mord">4</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 提到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">12</span><span class="mord"><span class="mord">8</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">25</span><span class="mord"><span class="mord">6</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>，6 任务均值是 30.2 和 29.5，相对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">8</span><span class="mord"><span class="mord">4</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 的 28.7 几乎不变。这条实验相当程度上排除了&quot;2D 基线被分辨率拖累&quot;的替代解释。</p><p><strong>哪种 3D 表示？</strong> 点云 63.2 &gt; 深度 42.0 &gt; 体素 39.5 &gt; 图像 28.7 &gt; RGB-D 27.8。有意思的是深度优于 RGB-D，作者据此推断这批任务更依赖低层控制而非场景理解。</p><p><strong>为什么是这个编码器？</strong> DP3 Encoder 63.2，而 PointNet 17.7、PointNet++ 2.2、PointNeXt 2.3、Point Transformer 1.0，预训练版本同样很差。逐步改造 PointNet 的实验定位到罪魁：去掉 T-Net 和 BatchNorm 后 PointNet 跳到 59.5 / 61.0。作者对 T-Net 的解释是固定相机下不需要特征变换。</p><p><strong>设计选择的净贡献</strong>：去掉裁剪 63.2→51.3（最大项）；去掉 LayerNorm 61.3；去掉投影头 62.2；<strong>保留颜色反而是 63.7</strong>，略高于默认的 63.2——去色是为了外观泛化而非精度，论文如实说明了这一点。把 DDIM 换成 DPM-solver++ 崩到 34.8。</p><p><strong>泛化与安全</strong>：空间/外观/实例/视角四类泛化实验里 DP3 大幅优于基线，但每个格子只有 1 次试验（5 个位置、5 种颜色、5 个实例、3 个视角各一次），样本量极小。安全违规率：DP3 0%，图像版 32.5%，深度版 25.0%，这一项是在主实验的 40 次真机试验中顺带统计的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：DP3 把 Diffusion Policy 的图像分支换成&quot;裁剪 + FPS 降采样 + 三层 MLP&quot;的点云编码器，输出 64 维条件向量。72 个仿真任务上相对 2D 版本有 55.3% 的相对提升，4 个真实任务用 40 条演示达到 85%。消融显示 3D 表示本身、裁剪先验、去掉颜色三者各自有贡献，且复杂点云编码器全面失败。真实实验中 DP3 从未触发安全干预，而两个基线分别是 32.5% 和 25%。方法简单到只改了一个模块，因此结论主要是&quot;表示选择比架构复杂度更重要&quot;。</p><p><strong>3 句话版</strong>：控制任务需要的是空间位置而非外观，点云把前者显式化。把扩散策略的条件换成 64 维点云特征，10 条演示即可覆盖大部分任务。复杂点云编码器不但没帮助，还因为 T-Net 与 BatchNorm 彻底失效。</p><p><strong>1 句话版</strong>：给扩散策略换上一个极简的稀疏点云编码器，就能把演示需求从上百条压到十条。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>每个任务的&quot;任务相关三维区域&quot;可以由人工预设的固定包围盒给出，且相机外参已标定</strong>。这条假设一旦不成立，方法的一大半优势就消失——消融里去掉裁剪，6 任务均值从 63.2 掉到 51.3，是所有设计选择中跌幅最大的一项；而 51.3 与&quot;深度图 + 图像编码器&quot;的 42.0 之间的差距已明显收窄。</p><p>它在实践中为什么可能不成立：包围盒是逐任务手工指定的，换场景、换桌高、换机器人底座位置都要重标；更直接的证据来自论文自己的视角泛化实验——作者写明&quot;由于相机视角被改变，我们手动调整了点云的裁剪空间&quot;。也就是说，被当作模型能力展示的视角泛化，实际上包含了一次人工重标定。论文为该假设提供的证据是充分的（裁剪消融做了），但没有提供&quot;自动确定裁剪区域&quot;或&quot;裁剪框失配时性能如何退化&quot;的任何数据，而这正是把方法搬到新场景时最先遇到的问题。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且不需要真机。取 MetaWorld 的 Assembly / Basketball / Shelf Place 与 Adroit 的 Hammer / Door / Pen 这 6 个消融任务（每任务 10 条演示，仿真器公开），训练四个变体：</p><ul><li>A：原版 DP3；</li><li>B：Diffusion Policy（图像，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">8</span><span class="mord"><span class="mord">4</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>）；</li><li>C：Diffusion Policy，但把图像按 DP3 的同一个 3D 包围盒投影到图像平面后裁剪，并转成灰度——即把&quot;工作空间先验 + 去色&quot;这两项非 3D 的因素补给 2D 基线；</li><li>D：DP3，但把包围盒放大 2 倍（模拟标定不准）。</li></ul><p>测量三种子下 6 任务平均成功率。若 C 与 A 的差距显著小于 B 与 A 的差距，则&quot;3D 的净贡献&quot;应被下修；若 D 明显退化到 51 附近，则裁剪先验的脆弱性被坐实。反之，若 C 仍远低于 A 且 D 变化不大，论文的归因得到支持。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击不是否认 3D 有用，而是指出<strong>比较的是两条不等长的信息通路</strong>。DP3 拿到的是：标定后的相机外参、逐任务的三维工作空间包围盒、以及一个只保留几何的输入；Diffusion Policy 拿到的是未裁剪、含纹理、且没有任何标定信息的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">8</span><span class="mord"><span class="mord">4</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 图像。作者已经排除了分辨率这一条替代解释（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">12</span><span class="mord"><span class="mord">8</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>/<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">25</span><span class="mord"><span class="mord">6</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 对照），但没有排除&quot;工作空间先验&quot;这一条，而它恰恰是消融中最大的单项。</p><p>一个可预测的失败场景同样值得设计：把相机换成手持或移动底盘上的相机，使外参逐帧变化。此时 T-Net 被移除的代价会显现——作者对 T-Net 的解释正是&quot;固定相机不需要特征变换&quot;，这句话反过来就是一个可证伪预测：在移动相机下，去掉 T-Net 的 DP3 Encoder 应当明显劣于带 T-Net 的版本。论文的全部实验都在固定单相机下完成，因此这个预测未被检验。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：论文把结论叙述为&quot;3D 表示重要&quot;，但消融给出的证据结构其实是&quot;工作空间裁剪 + 去纹理 + 64 维瓶颈&quot;三件事同时起作用，而这三件事都不必然要求深度传感器。与此同时，方法对标定和手工包围盒的依赖，恰好是它最难扩展的部分。</p><p><strong>新的 framing</strong>：把 DP3 的收益重新理解为&quot;控制需要的是一个与外观解耦的低维状态估计&quot;，而不是&quot;控制需要点云&quot;。若这个 framing 成立，那么 64 维的 DP3 特征可以当作教师，把它蒸馏进一个只吃 RGB 的编码器——深度相机只在数据采集期需要，部署期不需要。可借鉴的相邻领域工具是特权信息学习（learning with privileged information）与跨模态蒸馏：训练时用特权的几何通道，推理时只留下便宜的通道。</p><p><strong>第一个实验</strong>：在同样的 6 个消融任务上，先训好 DP3，冻结其编码器；再训练一个 ResNet-18 从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">8</span><span class="mord"><span class="mord">4</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> RGB 图像回归 DP3 的 64 维特征（回归损失用同一批演示，无需额外数据）；最后把这个 RGB 编码器接到扩散策略上评测。三个结果各有意义：追平 DP3 说明几何信息可以被单目蒸馏出来，深度传感器不是必需品；显著落后则说明确实存在单目无法恢复的几何量，可进一步定位是尺度还是遮挡；介于两者之间时，比较其与变体 C 的差距可以把&quot;先验&quot;与&quot;几何&quot;两部分贡献分开。</p>',51)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
